/* ZeroHour v2: dependency-free, browser-local, paper-first SSB practice. */
const app = document.getElementById("app");
const announcer = document.getElementById("announcer");
const KEY = { state: "zerohour-v2-state", banks: "zerohour-v2-custom-banks", history: "zerohour-v2-history", active: "zerohour-v2-active" };
const BACKUP_VERSION = 1;
const DEFAULT = {
  version: 2, mode: "WAT", bankIds: {},
  settings: { watSeconds: 10, watCount: 60, tatObserve: 30, tatStory: 180, tatCount: 12, ppdtObserve: 30, ppdtStory: 240, ppdtNarrate: 60, ppdtCount: 1, srtSeconds: 20, srtCount: 60, interviewSeconds: 60, interviewCount: 20, interviewPriority: "P0", interviewTopic: "All topics", shuffle: true, dedupe: true, beep: true, restEnabled: false, restSeconds: 5 }
};
const MODES = [
  { id: "WAT", short: "WAT", name: "Word Association Test", icon: "◉", desc: "One stimulus word at a time" },
  { id: "TAT", short: "TAT", name: "Thematic Apperception Test", icon: "▧", desc: "Picture observation + story writing" },
  { id: "PPDT", short: "PPDT", name: "Picture Perception & Discussion Test", icon: "▣", desc: "Observe, write, then narrate" },
  { id: "SRT", short: "SRT", name: "Situation Reaction Test", icon: "☷", desc: "Rapid paper responses to situations" },
  { id: "INTERVIEW", short: "TECH", name: "Technical Interview", icon: "⌘", desc: "CSE interview prompts and reference answers" }
];
let banks, state = structuredClone(DEFAULT), customBanks = {}, history = [], session = null, pendingRecovery = null;
let currentView = "practice", modal = null, timer = null, endsAt = null, materialManifest = null, toast = "", libraryQuery = "", libraryCategory = "All categories", reviewId = null, audioContext = null;
const $ = (selector, root = document) => root.querySelector(selector);
const esc = (value = "") => String(value).replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char]));
const fmt = value => { const s = Math.max(0, Math.floor(Number(value) || 0)), h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), r = s % 60; return h ? `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${String(r).padStart(2, "0")}` : `${String(m).padStart(2, "0")}:${String(r).padStart(2, "0")}`; };
const dur = value => value >= 60 ? `${Math.floor(value / 60)}m${value % 60 ? ` ${value % 60}s` : ""}` : `${value}s`;
const uid = prefix => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
const canonical = value => String(value || "").toLowerCase().replace(/\s+/g, " ").trim();
const imageMode = mode => mode === "TAT" || mode === "PPDT";
const modeInfo = () => MODES.find(mode => mode.id === state.mode) || MODES[0];
const prompt = (item, mode) => mode === "INTERVIEW" ? item?.question || "" : imageMode(mode) ? item?.title || "" : typeof item === "string" ? item : item?.text || "";
const say = message => { if (announcer) announcer.textContent = message; };

function load(key, fallback) { try { const raw = localStorage.getItem(key); return raw ? JSON.parse(raw) : fallback; } catch (error) { console.warn("ZeroHour storage read failed", error); return fallback; } }
function save(key, value) { try { localStorage.setItem(key, JSON.stringify(value)); return true; } catch (error) { console.error("ZeroHour storage write failed", error); toast = "Local storage is full or unavailable. Export a backup before continuing."; say(toast); return false; } }
function persist() { save(KEY.state, state); save(KEY.banks, customBanks); save(KEY.history, history.slice(0, 100)); }
function notice(message) { toast = message; say(message); render(); window.setTimeout(() => { if (toast === message) { toast = ""; render(); } }, 4500); }
function setupSaved() {
  const saved = load(KEY.state, load("zerohour-full-settings", null));
  if (saved && typeof saved === "object") state = { ...DEFAULT, ...saved, bankIds: { ...(saved.bankIds || {}) }, settings: { ...DEFAULT.settings, ...(saved.settings || {}) } };
  customBanks = load(KEY.banks, load("zerohour-custom-banks", {})) || {};
  history = load(KEY.history, load("zerohour-session-history", [])) || [];
  if (!Array.isArray(history)) history = [];
  pendingRecovery = load(KEY.active, null);
}
function saveActive(reason = "interrupted") {
  if (!session || session.completed) return;
  if (!session.paused && endsAt) session.remaining = Math.max(0, Math.ceil((endsAt - Date.now()) / 1000));
  save(KEY.active, { ...session, paused: true, activeStartedAt: null, savedAt: new Date().toISOString(), recoveryReason: reason });
}
function clearActive() { try { localStorage.removeItem(KEY.active); } catch (error) { console.warn(error); } }

function defaultBank(mode) { if (mode === "WAT") return banks.watBanks?.[0]?.id || ""; if (mode === "SRT") return banks.srtBanks?.[0]?.id || ""; if (mode === "INTERVIEW") return "cse-interview"; return "tat-467"; }
function selectedBank(mode = state.mode) { return state.bankIds?.[mode] || defaultBank(mode); }
function builtInItems(mode, id) {
  if (mode === "WAT") { const bank = banks.watBanks.find(item => item.id === id) || banks.watBanks[0]; return bank.items.map((text, index) => ({ id: `${bank.id}-${index + 1}`, text: String(text), source: bank.source, category: "WAT", extractionStatus: "source-derived" })); }
  if (mode === "SRT") { const bank = banks.srtBanks.find(item => item.id === id) || banks.srtBanks[0]; return bank.items.map((text, index) => ({ id: `${bank.id}-${index + 1}`, text: String(text), source: bank.source, category: "SRT", extractionStatus: "source-derived" })); }
  if (mode === "INTERVIEW") return banks.interviewItems.map((item, index) => ({ id: `cse-${index + 1}`, question: item.question, answer: item.answer, topic: item.topic || "Uncategorised", priority: item.priority || "P2", source: "AAB CSE Tech Interview Answer Book.pdf", page: item.page || null, category: "Technical interview", extractionStatus: "source-derived" }));
  return Array.from({ length: Number(banks.tatCount) || 0 }, (_, index) => { const number = String(index + 1).padStart(3, "0"); return { id: `tat-467-${number}`, title: `TAT / PPDT stimulus ${number}`, source: "TAT 467.pdf", page: index + 1, image: `assets/stimuli/tat467/processed/${number}.jpg`, thumbnail: `assets/stimuli/tat467/thumbs/${number}.jpg`, category: "TAT and PPDT", extractionStatus: "processed local source asset" }; });
}
function normalise(value, mode, bank, index) {
  const shared = { id: value?.id || `${bank.id}-${index + 1}`, source: value?.source || bank.source || "User-created material", page: value?.page || null, category: value?.category || mode, extractionStatus: "user-created" };
  if (mode === "INTERVIEW") return { ...shared, question: String(value?.question || value?.prompt || value?.text || "").trim(), answer: String(value?.answer || "").trim(), topic: value?.topic || "Custom", priority: value?.priority || "P2" };
  if (imageMode(mode)) return { ...shared, title: String(value?.title || value?.prompt || "Custom picture").trim(), image: value?.image || "", thumbnail: value?.thumbnail || value?.image || "" };
  return { ...shared, text: String(typeof value === "string" ? value : value?.text || value?.prompt || value?.word || value?.question || "").trim() };
}
function findCustom(mode, id) { return (customBanks[mode] || []).find(bank => bank.id === id); }
function itemsFor(mode, id) { const custom = findCustom(mode, id); return custom ? (custom.items || []).map((item, index) => normalise(item, mode, custom, index)).filter(item => prompt(item, mode)) : builtInItems(mode, id); }
function optionsFor(mode) {
  let original = [];
  if (mode === "WAT") original = banks.watBanks.map(bank => ({ id: bank.id, title: bank.title, source: bank.source, count: bank.items.length, original: true, category: "WAT" }));
  if (mode === "SRT") original = banks.srtBanks.map(bank => ({ id: bank.id, title: bank.title, source: bank.source, count: bank.items.length, note: bank.note, original: true, category: "SRT" }));
  if (mode === "INTERVIEW") original = [{ id: "cse-interview", title: `CSE technical interview (${banks.interviewItems.length})`, source: "AAB CSE Tech Interview Answer Book.pdf", count: banks.interviewItems.length, original: true, category: "Technical interview" }];
  if (imageMode(mode)) original = [{ id: "tat-467", title: `TAT / PPDT picture bank (${banks.tatCount})`, source: "TAT 467.pdf", count: banks.tatCount, original: true, category: "TAT and PPDT" }];
  return [...original, ...(customBanks[mode] || []).map(bank => ({ ...bank, count: (bank.items || []).length, original: false }))];
}
function unique(items, mode) { const seen = new Set(), kept = []; let duplicates = 0; for (const item of items) { const key = canonical(imageMode(mode) ? item.image || item.title : prompt(item, mode)); if (seen.has(key)) duplicates += 1; else { seen.add(key); kept.push(item); } } return { kept, duplicates }; }
function shuffle(items) { const copy = [...items]; for (let i = copy.length - 1; i > 0; i -= 1) { const j = Math.floor(Math.random() * (i + 1)); [copy[i], copy[j]] = [copy[j], copy[i]]; } return copy; }
function phaseSeconds(mode, phase) { const s = state.settings; if (phase === "rest") return s.restSeconds; if (mode === "WAT") return s.watSeconds; if (mode === "SRT") return s.srtSeconds; if (mode === "INTERVIEW") return s.interviewSeconds; if (mode === "TAT") return phase === "observe" ? s.tatObserve : s.tatStory; return phase === "observe" ? s.ppdtObserve : phase === "story" ? s.ppdtStory : s.ppdtNarrate; }
function firstPhase(mode) { return imageMode(mode) ? "observe" : "item"; }

function render() {
  if (!banks) return;
  const mode = modeInfo();
  app.innerHTML = `<aside class="sidebar" aria-label="ZeroHour navigation"><div class="brand"><div class="brand-shield">⬡</div><div><div class="brand-name">ZERO<span>HOUR</span></div><div class="brand-caption">SSB PRACTICE SUITE</div></div></div><div class="side-label">TRAINING MODULES</div><nav class="nav-list">${MODES.map(entry => navMode(entry)).join("")}</nav><div class="sidebar-divider"></div><div class="side-label">WORKSPACE</div>${navView("practice", "◷", "Practice", "Timed test sessions")}${navView("library", "▤", "Material library", "Sources and bank tools")}${navView("history", "▥", "Session history", "Past practice runs")}${navView("analytics", "◫", "Analytics", "Personal tracking")}<div class="sidebar-bottom"><span class="online-dot"></span> LOCAL MODE · PRIVATE<br/><small>Paper first. No answer entry needed.</small></div></aside><main class="main" id="mainContent" tabindex="-1">${header(mode)}${currentView === "library" ? libraryView() : currentView === "history" ? historyView() : currentView === "analytics" ? analyticsView() : session ? sessionView() : setupView()}<footer class="footer"><span>ZEROHOUR // SSB PRACTICE TRACKER</span><span>YOUR MATERIAL · YOUR PAPER · YOUR PACE</span></footer></main>${toast ? `<div class="toast" role="status">${esc(toast)}</div>` : ""}${modal ? modalView() : ""}`;
}
function navMode(entry) { return `<button class="nav-item ${state.mode === entry.id ? "active" : ""}" data-action="mode" data-mode="${entry.id}"><span class="nav-symbol">${entry.icon}</span><span class="nav-copy"><b>${entry.short}</b><small>${entry.name}</small></span><span class="nav-arrow">›</span></button>`; }
function navView(view, icon, title, detail) { return `<button class="nav-item ${currentView === view ? "active" : ""}" data-action="view" data-view="${view}"><span class="nav-symbol">${icon}</span><span class="nav-copy"><b>${title}</b><small>${detail}</small></span></button>`; }
function header(mode) {
  const title = currentView === "library" ? "Material Library" : currentView === "history" ? "Session History" : currentView === "analytics" ? "Personal Analytics" : session ? session.completed ? "Session Review" : "Live Practice" : mode.name;
  const subtitle = currentView === "library" ? "Original source materials remain distinct from user-created banks." : currentView === "history" ? "Review only the stimuli associated with each completed run." : currentView === "analytics" ? "Personal practice tracking, not a formal SSB assessment." : session && !session.completed ? "Keep your attention on your paper and the timer." : mode.desc;
  return `<header class="topbar"><div><div class="breadcrumb">ZEROHOUR / ${esc(currentView.toUpperCase())} / <b>${esc(mode.short)}</b></div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="top-actions"><button class="btn btn-quiet" data-action="fullscreen">${document.fullscreenElement ? "⛶ Exit fullscreen" : "⛶ Fullscreen"}</button><button class="btn btn-quiet" data-action="backup">⇅ Backup</button><button class="btn btn-quiet" data-action="settings">⚙ Settings</button></div></header>`;
}
function stat(label, value, note) { return `<div class="stat-card"><div class="stat-label">${esc(label)}</div><div class="stat-number">${esc(value)}</div><div class="stat-note">${esc(note)}</div></div>`; }
function setupView() {
  const mode = modeInfo(), options = optionsFor(state.mode), selected = selectedBank(), bank = options.find(entry => entry.id === selected) || options[0], s = state.settings;
  const count = state.mode === "WAT" ? s.watCount : state.mode === "SRT" ? s.srtCount : state.mode === "TAT" ? s.tatCount : state.mode === "PPDT" ? s.ppdtCount : s.interviewCount;
  const sec = state.mode === "WAT" ? s.watSeconds : state.mode === "SRT" ? s.srtSeconds : state.mode === "TAT" ? s.tatStory : state.mode === "PPDT" ? s.ppdtStory : s.interviewSeconds;
  const estimate = state.mode === "TAT" ? count * (s.tatObserve + s.tatStory) : state.mode === "PPDT" ? count * (s.ppdtObserve + s.ppdtStory + s.ppdtNarrate) : count * sec;
  const topics = [...new Set((banks.interviewItems || []).map(item => item.topic))];
  const message = state.mode === "TAT" || state.mode === "PPDT" ? "The picture will be visible only in the observation phase and is never present in the writing or narration phase." : state.mode === "WAT" ? "Write a natural response on paper before the next word appears." : state.mode === "SRT" ? "Respond practically and concisely on paper." : "Answer aloud or on paper; source answers are optional.";
  return `<section class="stats-grid">${stat("AVAILABLE PROMPTS", String(bank?.count || 0), bank?.title || "No bank")}${stat("DEFAULT PACE", `${dur(sec)} / item`, imageMode(state.mode) ? "plus observation" : "editable")}${stat("ESTIMATED RUN", fmt(estimate), `${count} prompts`)}</section><section class="setup-card"><div class="section-heading"><div><div class="eyebrow">MISSION CONFIGURATION</div><h2>Build a paper-first practice run</h2><p>${esc(message)}</p></div><span class="lock-chip">◈ NO TYPING REQUIRED</span></div><div class="setup-grid"><div class="setup-form"><label class="field"><span>Question bank / source set</span><select id="bankSelect">${options.map(entry => `<option value="${esc(entry.id)}" ${entry.id === selected ? "selected" : ""}>${esc(entry.title)}${entry.original ? " · original" : " · custom"}</option>`).join("")}</select><small>${esc(bank?.source || "")}${bank?.note ? ` · ${esc(bank.note)}` : ""}</small></label>${state.mode === "INTERVIEW" ? `<div class="field-grid two"><label class="field"><span>Priority</span><select id="interviewPriority"><option value="ALL" ${s.interviewPriority === "ALL" ? "selected" : ""}>All priorities</option>${["P0", "P1", "P2", "P3"].map(value => `<option ${s.interviewPriority === value ? "selected" : ""}>${value}</option>`).join("")}</select></label><label class="field"><span>Topic</span><select id="interviewTopic"><option ${s.interviewTopic === "All topics" ? "selected" : ""}>All topics</option>${topics.map(topic => `<option ${s.interviewTopic === topic ? "selected" : ""}>${esc(topic)}</option>`).join("")}</select></label></div>` : ""}<div class="field-grid two"><label class="field"><span>Items in this run</span><input id="itemCount" type="number" min="1" max="5000" value="${count}"/></label><label class="field"><span>${state.mode === "WAT" ? "Seconds per word" : state.mode === "SRT" ? "Seconds per situation" : state.mode === "INTERVIEW" ? "Seconds per question" : "Story-writing time (sec)"}</span><input id="itemSeconds" type="number" min="1" max="3600" value="${sec}"/></label></div>${state.mode === "TAT" ? `<div class="inline-settings">${num("observeSeconds", "Observation (sec)", s.tatObserve, 1, 300)}</div>` : ""}${state.mode === "PPDT" ? `<div class="inline-settings">${num("observeSeconds", "Observation (sec)", s.ppdtObserve, 1, 300)}${num("narrateSeconds", "Narration (sec)", s.ppdtNarrate, 1, 600)}</div>` : ""}<label class="check-field"><input id="shuffle" type="checkbox" ${s.shuffle ? "checked" : ""}/><span><b>Shuffle question order</b><small>Creates a different sequence from the chosen source.</small></span></label><label class="check-field"><input id="dedupe" type="checkbox" ${s.dedupe ? "checked" : ""}/><span><b>Suppress exact duplicate prompts</b><small>Does not alter the original source bank.</small></span></label><div class="form-actions"><button class="btn btn-primary" data-action="start">▶ Start timed session <span>→</span></button><button class="btn btn-secondary" data-action="import">＋ Create/import bank</button></div></div><div class="setup-aside"><div class="aside-icon">${mode.icon}</div><div class="eyebrow">SESSION PROTOCOL</div><h3>${esc(mode.short)} <span>SIMULATION</span></h3><p>${esc(message)}</p><div class="protocol-list"><div><i>01</i><span>One prompt at a time</span></div><div><i>02</i><span>Write on paper, not in the app</span></div><div><i>03</i><span>Pause and recovery are safe</span></div><div><i>04</i><span>Review after the run</span></div></div><div class="source-tag">SOURCE <b>${esc(bank?.source || "No source")}</b></div></div></div></section><section class="below-grid"><div class="mini-card"><div class="mini-head"><span>◷</span><b>QUICK TIMING PRESETS</b></div><div class="preset-buttons">${presets(state.mode).map(value => `<button data-action="preset" data-seconds="${value}">${dur(value)}</button>`).join("")}</div><small>Applies to the current writing/question phase.</small></div><div class="mini-card"><div class="mini-head"><span>▤</span><b>LOCAL MATERIALS</b></div><p>Original source banks and extracted files stay separate from custom material. Search source inventory and manage imported banks in the library.</p><button class="text-button" data-action="view" data-view="library">Open material library →</button></div></section>`;
}
function presets(mode) { return mode === "WAT" ? [5, 10, 15] : mode === "SRT" ? [15, 20, 30] : mode === "INTERVIEW" ? [30, 60, 90] : mode === "TAT" ? [120, 180, 240] : [180, 240, 300]; }
function num(id, label, value, min = 1, max = 3600) { return `<label class="field compact"><span>${esc(label)}</span><input id="${id}" type="number" min="${min}" max="${max}" value="${value}"/></label>`; }

function sessionView() {
  if (session.completed) return reviewView(session, true);
  const item = session.items[session.index], showImage = imageMode(session.mode) && session.phase === "observe", hidden = imageMode(session.mode) && !showImage && session.phase !== "rest";
  const phaseName = { item: "WRITE YOUR RESPONSE", observe: "OBSERVE THE PICTURE", story: "STORY WRITING", narrate: "NARRATION PRACTICE", rest: "REST BREAK" }[session.phase] || "PRACTICE";
  const hint = session.mode === "WAT" ? "Write one spontaneous sentence on paper." : session.mode === "SRT" ? "Write a short, practical response on paper." : session.mode === "INTERVIEW" ? "Answer aloud or on paper. The source answer remains optional." : session.phase === "observe" ? "Study the picture. Do not write yet." : session.phase === "story" ? "Write your story on paper. The picture is no longer available during this phase." : session.phase === "narrate" ? "Narrate clearly. The picture remains hidden." : "Reset before the next item.";
  const progress = Math.round(session.index / session.items.length * 100);
  return `<section class="live-shell"><div class="live-toolbar"><div><div class="eyebrow">LIVE SESSION · ${esc(session.mode)}</div><div class="item-index">ITEM <b>${String(session.index + 1).padStart(2, "0")}</b><span>/ ${String(session.items.length).padStart(2, "0")}</span></div></div><div class="live-status ${session.paused ? "paused" : ""}"><span class="online-dot"></span>${session.paused ? "PAUSED" : "TIMER ACTIVE"}</div><button class="btn btn-quiet" data-action="finish">Finish early</button></div><div class="overall-progress"><div style="width:${progress}%"></div></div><div class="live-timer-card"><div class="phase-line"><span>${esc(phaseName)}</span><span>${session.phase === "item" ? "TIMED PROMPT" : session.phase === "rest" ? "PREPARE" : `PHASE ${session.phase === "observe" ? "1" : session.phase === "story" ? "2" : "3"}`}</span></div><div class="countdown-display ${session.remaining <= 5 && !session.paused ? "urgent" : ""}"><div class="clock-label">${session.phase === "rest" ? "RESET BEFORE NEXT ITEM" : session.mode === "WAT" ? "STIMULUS WORD" : session.mode === "SRT" ? "SITUATION" : session.mode === "INTERVIEW" ? "INTERVIEW QUESTION" : session.phase === "observe" ? "PICTURE PROMPT" : "PAPER RESPONSE TIME"}</div><div id="clockValue">${fmt(session.remaining)}</div><div class="clock-sub">ITEM ${session.index + 1} OF ${session.items.length} · <span id="elapsedLive">${fmt(elapsed())}</span> ELAPSED</div></div>${showImage ? imageStage(item) : ""}${hidden ? `<div class="picture-hidden" role="status"><span>▧</span><b>PICTURE HIDDEN</b><small>The stimulus is unavailable until post-test review.</small></div>` : ""}<div class="prompt-zone ${session.mode === "WAT" ? "wat-prompt" : ""}">${session.mode === "INTERVIEW" ? `<div class="priority-chip ${esc(String(item.priority).toLowerCase())}">${esc(item.priority)} · ${esc(item.topic)}</div><div class="prompt-text">${esc(prompt(item, session.mode))}</div><details class="during-answer"><summary>Reveal source reference answer (optional)</summary><p>${esc(item.answer)}</p></details>` : imageMode(session.mode) ? `<div class="prompt-text small-prompt">${esc(hint)}</div>` : `<div class="prompt-text">${esc(prompt(item, session.mode))}</div><p class="prompt-instruction">${esc(hint)}</p>`}</div><div class="live-controls">${session.paused ? `<button class="btn btn-primary" data-action="resume">▶ Resume</button>` : `<button class="btn btn-primary" data-action="pause">Ⅱ Pause timer</button>`}<button class="btn btn-secondary" data-action="restart">↻ Restart phase</button><button class="btn btn-secondary" data-action="skip">Skip item →</button><button class="btn btn-quiet" data-action="mute">${state.settings.beep ? "🔊 Alert on" : "🔇 Alert off"}</button></div><div class="time-track"><div id="timeFill" class="${session.remaining <= 5 ? "urgent" : ""}" style="width:${Math.max(0, session.remaining / session.phaseDuration * 100)}%"></div></div></div><div class="live-foot"><span><i class="online-dot"></i> Paper-based mode · No typing required · <kbd>Space</kbd> pause · <kbd>→</kbd> skip · <kbd>R</kbd> restart</span><span>${session.shownCount} seen <b>·</b> ${session.items.length - session.shownCount} remaining</span></div></section>`;
}
function imageStage(item) { return item.image ? `<div class="image-stage"><img class="stimulus-image" src="${esc(item.image)}" alt="${esc(item.title)}" data-image-path="${esc(item.image)}"/><div class="image-caption">${esc(item.title)} <span>· ${esc(item.source)} · PAGE ${item.page}</span></div></div>` : `<div class="image-fallback"><b>Stimulus image unavailable</b><small>${esc(item.source || "No local image path")}</small></div>`; }

function start() {
  const mode = state.mode, bankId = selectedBank(mode), original = itemsFor(mode, bankId), clean = state.settings.dedupe ? unique(original, mode) : { kept: original, duplicates: 0 };
  let items = state.settings.shuffle ? shuffle(clean.kept) : clean.kept;
  const configured = mode === "WAT" ? state.settings.watCount : mode === "SRT" ? state.settings.srtCount : mode === "TAT" ? state.settings.tatCount : mode === "PPDT" ? state.settings.ppdtCount : state.settings.interviewCount;
  items = items.slice(0, Math.max(1, Math.min(Number(configured) || 1, items.length)));
  if (!items.length) { notice("This bank or filter has no valid prompts. Choose another source or import a bank."); return; }
  const bank = optionsFor(mode).find(item => item.id === bankId);
  session = { id: uid("session"), mode, bankId, bankTitle: bank?.title || "Selected bank", source: bank?.source || "Unknown source", items, index: 0, phase: firstPhase(mode), phaseDuration: 0, remaining: 0, paused: false, completed: false, startedAt: new Date().toISOString(), elapsedBefore: 0, activeStartedAt: Date.now(), shownCount: 0, skippedCount: 0, suppressedDuplicates: clean.duplicates, itemStatus: {}, note: "", selfRating: "", focusTopics: "" };
  currentView = "practice"; startPhase(session.phase); say(`${modeInfo().name} started.`);
}
function elapsed(record = session) { if (!record) return 0; return Math.max(0, Number(record.elapsedBefore || record.elapsed || 0) + (record.activeStartedAt ? Math.floor((Date.now() - record.activeStartedAt) / 1000) : 0)); }
function settle() { if (session?.activeStartedAt) { session.elapsedBefore = elapsed(); session.activeStartedAt = null; } }
function startPhase(phase, newClock = true) { if (!session || session.completed) return; clearTimer(); session.phase = phase; session.phaseDuration = phaseSeconds(session.mode, phase); if (newClock) session.remaining = session.phaseDuration; session.paused = false; if (!session.activeStartedAt) session.activeStartedAt = Date.now(); endsAt = Date.now() + session.remaining * 1000; session.shownCount = Math.max(session.shownCount, phase === "rest" ? session.index : session.index + 1); saveActive("active"); timer = setInterval(tick, 125); render(); }
function clearTimer() { if (timer) clearInterval(timer); timer = null; endsAt = null; }
function remaining() { return endsAt ? Math.max(0, Math.ceil((endsAt - Date.now()) / 1000)) : Math.max(0, Number(session?.remaining) || 0); }
function tick() { if (!session || session.completed || session.paused) return; session.remaining = remaining(); const clock = $("#clockValue"), fill = $("#timeFill"), active = $("#elapsedLive"); if (clock) clock.textContent = fmt(session.remaining); if (fill) { fill.style.width = `${Math.max(0, Math.min(100, session.remaining / session.phaseDuration * 100))}%`; fill.classList.toggle("urgent", session.remaining <= 5); } if (active) active.textContent = fmt(elapsed()); if (session.remaining % 5 === 0 && session.lastSaved !== session.remaining) { session.lastSaved = session.remaining; saveActive("active"); } if (session.remaining <= 0) { clearTimer(); if (state.settings.beep) beep(); advance(); } }
function beep() { try { audioContext = audioContext || new (window.AudioContext || window.webkitAudioContext)(); const osc = audioContext.createOscillator(), gain = audioContext.createGain(); osc.connect(gain); gain.connect(audioContext.destination); osc.frequency.value = 880; gain.gain.setValueAtTime(.08, audioContext.currentTime); gain.gain.exponentialRampToValueAtTime(.001, audioContext.currentTime + .2); osc.start(); osc.stop(audioContext.currentTime + .22); } catch (error) { console.warn("Audio unavailable", error); } }
function advance() { if (!session) return; if (session.phase === "rest") return next(); if (imageMode(session.mode) && session.phase === "observe") return startPhase("story"); if (session.mode === "PPDT" && session.phase === "story") return startPhase("narrate"); if (state.settings.restEnabled && session.index < session.items.length - 1) return startPhase("rest"); next(); }
function next() { if (!session) return; if (session.index + 1 >= session.items.length) return complete(false); session.index += 1; startPhase(firstPhase(session.mode)); }
function pause(reason = "paused") { if (!session || session.completed || session.paused) return; session.remaining = remaining(); settle(); clearTimer(); session.paused = true; saveActive(reason); render(); say("Timer paused."); }
function resume() { if (!session || session.completed || !session.paused) return; session.paused = false; session.activeStartedAt = Date.now(); endsAt = Date.now() + Math.max(1, session.remaining) * 1000; timer = setInterval(tick, 125); saveActive("active"); render(); say("Timer resumed."); }
function restart() { if (!session || session.completed) return; settle(); session.remaining = phaseSeconds(session.mode, session.phase); startPhase(session.phase); }
function skip() { if (!session || session.completed) return; session.itemStatus[session.items[session.index].id] = "skipped"; session.skippedCount += 1; settle(); if (state.settings.restEnabled && session.index < session.items.length - 1) startPhase("rest"); else next(); }
function complete(early) { if (!session || session.completed) return; settle(); clearTimer(); session.completed = true; session.endedAt = new Date().toISOString(); session.elapsed = elapsed(); session.endedEarly = Boolean(early); history = [structuredClone(session), ...history.filter(entry => entry.id !== session.id)].slice(0, 100); clearActive(); persist(); render(); say(early ? "Session saved as an early finish." : "Session complete."); }
function discard() { clearTimer(); session = null; pendingRecovery = null; clearActive(); render(); }

function capture() {
  const s = state.settings, selected = $("#bankSelect"); if (selected) state.bankIds[state.mode] = selected.value;
  const value = (id, fallback, min = 1, max = 5000) => { const number = Number($("#" + id)?.value); return Number.isFinite(number) ? Math.max(min, Math.min(max, Math.floor(number))) : fallback; };
  if (state.mode === "WAT") { s.watCount = value("itemCount", s.watCount); s.watSeconds = value("itemSeconds", s.watSeconds, 1, 120); }
  if (state.mode === "SRT") { s.srtCount = value("itemCount", s.srtCount); s.srtSeconds = value("itemSeconds", s.srtSeconds, 1, 120); }
  if (state.mode === "INTERVIEW") { s.interviewCount = value("itemCount", s.interviewCount); s.interviewSeconds = value("itemSeconds", s.interviewSeconds, 1, 3600); s.interviewPriority = $("#interviewPriority")?.value || s.interviewPriority; s.interviewTopic = $("#interviewTopic")?.value || s.interviewTopic; }
  if (state.mode === "TAT") { s.tatCount = value("itemCount", s.tatCount, 1, banks.tatCount); s.tatStory = value("itemSeconds", s.tatStory, 1, 3600); s.tatObserve = value("observeSeconds", s.tatObserve, 1, 300); }
  if (state.mode === "PPDT") { s.ppdtCount = value("itemCount", s.ppdtCount, 1, banks.tatCount); s.ppdtStory = value("itemSeconds", s.ppdtStory, 1, 3600); s.ppdtObserve = value("observeSeconds", s.ppdtObserve, 1, 300); s.ppdtNarrate = value("narrateSeconds", s.ppdtNarrate, 1, 600); }
  s.shuffle = Boolean($("#shuffle")?.checked); s.dedupe = Boolean($("#dedupe")?.checked); persist();
}

function reviewView(record, current) {
  const shown = record.items.slice(0, Math.max(Number(record.shownCount || 0), record.endedEarly ? record.index + 1 : record.items.length));
  return `<section class="review-shell"><div class="debrief-hero"><div class="debrief-check">${record.endedEarly ? "!" : "✓"}</div><div><div class="eyebrow">${record.endedEarly ? "SESSION SAVED EARLY" : "SESSION COMPLETE"}</div><h2>Paper-first review</h2><p>These are the exact stimuli logged for this run. Personal ratings track practice only; they are not official SSB scores.</p></div></div><div class="debrief-stats"><div><span>ITEMS SEEN</span><b>${record.shownCount || shown.length}</b></div><div><span>SKIPPED</span><b>${record.skippedCount || 0}</b></div><div><span>ACTIVE TIME</span><b>${fmt(record.elapsed || elapsed(record))}</b></div><div><span>MODE</span><b>${esc(record.mode)}</b></div></div><div class="debrief-actions"><button class="btn btn-primary" data-action="export-session" data-id="${esc(record.id)}">↓ Export session log</button>${current ? `<button class="btn btn-secondary" data-action="new-run">↻ New run</button><button class="btn btn-secondary" data-action="setup">Back to setup</button>` : `<button class="btn btn-secondary" data-action="history">Back to history</button>`}</div><section class="reflection-card"><div><div class="eyebrow">PERSONAL DEBRIEF</div><h3>Reflection and practice focus</h3><p>Record your own observations and topics needing practice.</p></div><div class="field-grid two"><label class="field"><span>Personal self-rating</span><select id="selfRating"><option value="" ${!record.selfRating ? "selected" : ""}>Not rated</option>${[1,2,3,4,5].map(value => `<option value="${value}" ${String(record.selfRating) === String(value) ? "selected" : ""}>${value} / 5</option>`).join("")}</select></label><label class="field"><span>Topics to practise</span><input id="focusTopics" value="${esc(record.focusTopics || "")}" placeholder="e.g. calm narration, networking"/></label></div><label class="field"><span>Personal reflection</span><textarea id="sessionNote" rows="4" placeholder="What worked? What will you improve next time?">${esc(record.note || "")}</textarea></label><button class="btn btn-secondary" data-action="save-notes" data-id="${esc(record.id)}">Save reflection</button></section><div class="question-log"><div class="log-heading"><span>STIMULI ENCOUNTERED</span><span>${shown.length} ITEMS</span></div>${shown.map((item, index) => `<div class="log-row"><span class="log-num">${String(index + 1).padStart(2, "0")}</span>${imageMode(record.mode) ? `<img class="log-thumb" loading="lazy" src="${esc(item.thumbnail || item.image)}" alt="${esc(item.title)}"/>` : ""}<div class="log-prompt"><b>${esc(prompt(item, record.mode))}</b><small>${esc(item.source || record.source || "Unknown source")}${item.page ? ` · page ${item.page}` : ""}${item.extractionStatus ? ` · ${esc(item.extractionStatus)}` : ""}</small>${record.mode === "INTERVIEW" ? `<details><summary>View source reference answer</summary><p>${esc(item.answer || "No source answer extracted.")}</p><small>${esc(item.topic || "")}${item.priority ? ` · ${esc(item.priority)}` : ""}</small></details>` : ""}</div><span class="log-tag">${record.itemStatus?.[item.id] === "skipped" ? "SKIPPED" : "SHOWN"}</span></div>`).join("")}</div></section>`;
}

function libraryView() {
  const sources = materialManifest?.files || [], categories = ["All categories", ...new Set(sources.map(item => item.category).filter(Boolean))];
  const query = canonical(libraryQuery), rows = sources.filter(item => (!query || canonical(`${item.archive_member} ${item.category} ${item.text_status}`).includes(query)) && (libraryCategory === "All categories" || item.category === libraryCategory)).slice(0, 150);
  const originals = MODES.flatMap(mode => optionsFor(mode.id).filter(item => item.original));
  const custom = MODES.flatMap(mode => (customBanks[mode.id] || []).map(bank => ({ ...bank, mode: mode.id })));
  return `<section class="materials-page"><div class="section-heading"><div><div class="eyebrow">LOCAL SOURCE MATERIALS</div><h2>Materials, source banks and imports</h2><p>Both supplied ZIP archives are processed locally. Original sources are separate from custom banks and are never sent to a service.</p></div><div class="button-row"><button class="btn btn-secondary" data-action="import">＋ Create/import bank</button><button class="btn btn-secondary" data-action="backup">⇅ Backup & restore</button></div></div><div class="materials-summary">${stat("ORIGINAL BANKS", String(originals.length), "built-in source sets")}${stat("CUSTOM BANKS", String(custom.length), "user-created only")}${stat("MATERIAL FILES", materialManifest ? String(sources.length) : "…", materialManifest ? "local manifest loaded" : "manifest loading/unavailable")}${stat("EXTRACTION FLAGS", String(materialManifest?.warnings?.length || 0), "OCR or format review")}</div><section class="library-panel"><div class="library-title">SOURCE INVENTORY</div><div class="library-tools"><label class="field"><span>Search</span><input id="librarySearch" value="${esc(libraryQuery)}" placeholder="e.g. lecturette, scanned, TAT"/></label><label class="field"><span>Category</span><select id="libraryCategory">${categories.map(category => `<option ${category === libraryCategory ? "selected" : ""}>${esc(category)}</option>`).join("")}</select></label></div>${materialManifest ? `<p class="muted-copy">Showing ${rows.length} of ${sources.length} local files. Text-poor PDFs and legacy formats are flagged, never guessed.</p><div class="source-list">${rows.map(item => `<div class="source-row"><div><b>${esc(item.archive_member)}</b><small>${esc(item.category || "Uncategorised")} · ${Number(item.size_bytes || 0).toLocaleString()} bytes${item.page_count ? ` · ${item.page_count} pages` : ""}</small></div><span class="status-chip ${statusClass(item.text_status)}">${esc(item.text_status || item.extraction_status || "not inspected")}</span></div>`).join("") || `<div class="empty-state">No materials match this filter.</div>`}</div>` : `<div class="empty-state"><b>Source inventory is not available yet.</b><p>Run the bundled offline material processor, then refresh the page.</p></div>`}</section><section class="library-grid"><div class="library-panel"><div class="library-title">BUILT-IN SOURCE BANKS</div>${originals.map(item => `<div class="bank-row"><div><b>${esc(item.title)}</b><small>${esc(item.source)} · original source bank</small></div><span>${item.count.toLocaleString()} prompts</span></div>`).join("")}</div><div class="library-panel"><div class="library-title">CUSTOM BANKS</div>${custom.length ? custom.map(bank => `<div class="bank-row custom-bank-row"><div><b>${esc(bank.title)}</b><small>${esc(bank.mode)} · ${esc(bank.source || "User-created material")} · ${bank.stats?.valid ?? bank.items?.length ?? 0} valid · ${bank.stats?.duplicates || 0} duplicates excluded</small></div><div class="bank-actions"><button class="text-button" data-action="export-bank" data-mode="${bank.mode}" data-bank="${esc(bank.id)}">Export</button><button class="text-button danger-text" data-action="delete-bank" data-mode="${bank.mode}" data-bank="${esc(bank.id)}">Delete</button></div></div>`).join("") : `<div class="empty-state">No custom banks yet.</div>`}</div></section></section>`;
}
function statusClass(status) { const value = String(status || ""); return value.startsWith("extracted") ? "ok" : value.startsWith("partial") || value.startsWith("needs OCR") || value.startsWith("unsupported") ? "warn" : ""; }
function historyView() { if (reviewId) { const record = history.find(item => item.id === reviewId); if (record) return reviewView(record, false); reviewId = null; } if (!history.length) return `<section class="empty-history"><div class="empty-icon">▥</div><h2>No completed sessions yet</h2><p>Completed practice runs will appear here with their exact source references.</p><button class="btn btn-primary" data-action="view" data-view="practice">Start practising →</button></section>`; return `<section class="history-page"><div class="section-heading"><div><div class="eyebrow">AFTER ACTION REPORTS</div><h2>Session history</h2><p>Saved locally in this browser. Use versioned backups before clearing browser data.</p></div><button class="btn btn-secondary" data-action="clear-history">Clear history</button></div>${history.map(record => `<div class="history-row"><div class="history-icon">${esc(record.mode)}</div><div class="history-main"><b>${esc(record.bankTitle || `${record.mode} session`)}</b><small>${new Date(record.endedAt || record.startedAt).toLocaleString()} · ${record.shownCount || record.items?.length || 0} prompts${record.endedEarly ? " · ended early" : ""}</small></div><div class="history-time"><b>${fmt(record.elapsed || elapsed(record))}</b><small>active time</small></div><button class="btn btn-quiet" data-action="review" data-id="${esc(record.id)}">Review</button><button class="btn btn-quiet" data-action="export-session" data-id="${esc(record.id)}">Export</button></div>`).join("")}</section>`; }
function analyticsView() { const sessions = history.filter(item => item.endedAt), total = sessions.reduce((sum, item) => sum + Number(item.elapsed || elapsed(item)), 0), used = Object.fromEntries(MODES.map(mode => [mode.id, sessions.filter(item => item.mode === mode.id).length])); const days = [...new Set(sessions.map(item => new Date(item.endedAt || item.startedAt).toISOString().slice(0, 10)))].sort().reverse(); let streak = 0, cursor = new Date(); cursor.setHours(0,0,0,0); for (const day of days) { const date = new Date(`${day}T00:00:00`); if (date.getTime() === cursor.getTime()) { streak += 1; cursor.setDate(cursor.getDate()-1); } else if (date < cursor) break; } const focus = [...new Set(sessions.flatMap(item => String(item.focusTopics || "").split(/[,;\n]/)).map(item => item.trim()).filter(Boolean))]; return `<section class="analytics-page"><div class="section-heading"><div><div class="eyebrow">PERSONAL PRACTICE TRACKING</div><h2>Consistency and reflection</h2><p>These figures track your own practice activity only. They are not formal psychological scores and do not predict selection.</p></div></div><div class="stats-grid">${stat("COMPLETED RUNS", String(sessions.length), "saved sessions")}${stat("ACTIVE PRACTICE TIME", fmt(total), "paused/offline time excluded")}${stat("CURRENT STREAK", `${streak} days`, "from local completed sessions")}${stat("PROMPTS ENCOUNTERED", String(sessions.reduce((sum,item) => sum + Number(item.shownCount || item.items?.length || 0), 0)), "all modes")}</div><section class="library-grid"><div class="library-panel"><div class="library-title">SESSIONS BY MODE</div>${MODES.map(mode => `<div class="bank-row"><div><b>${esc(mode.name)}</b><small>${esc(mode.desc)}</small></div><span>${used[mode.id]} sessions</span></div>`).join("")}</div><div class="library-panel"><div class="library-title">SELF-IDENTIFIED PRACTICE TOPICS</div>${focus.length ? `<div class="topic-cloud">${focus.slice(0, 16).map(topic => `<span>${esc(topic)}</span>`).join("")}</div>` : `<div class="empty-state">Add practice topics during review to see them here.</div>`}</div></section></section>`; }

function modalView() { if (modal.type === "settings") return settingsModal(); if (modal.type === "import") return importModal(); if (modal.type === "backup") return backupModal(); if (modal.type === "restore") return restoreModal(); return recoveryModal(); }
function wrap(content) { return `<div class="modal-backdrop" data-action="close-modal"><div class="settings-modal" role="dialog" aria-modal="true">${content}</div></div>`; }
function close() { return `<button class="close-button" data-action="close-modal" aria-label="Close dialog">×</button>`; }
function settingsModal() { const s = state.settings; return wrap(`<div class="modal-title"><div><div class="eyebrow">CUSTOM TIMINGS</div><h2>Practice settings</h2></div>${close()}</div><div class="settings-section"><h3>WAT</h3><div class="field-grid two">${num("watSeconds", "Seconds per word", s.watSeconds, 1, 120)}${num("watCount", "Words per run", s.watCount)}</div></div><div class="settings-section"><h3>TAT</h3><div class="field-grid three">${num("tatObserve", "Observe", s.tatObserve, 1, 300)}${num("tatStory", "Story", s.tatStory)}${num("tatCount", "Stories", s.tatCount, 1, banks.tatCount)}</div></div><div class="settings-section"><h3>PPDT</h3><div class="field-grid four">${num("ppdtObserve", "Observe", s.ppdtObserve, 1, 300)}${num("ppdtStory", "Story", s.ppdtStory)}${num("ppdtNarrate", "Narrate", s.ppdtNarrate, 1, 600)}${num("ppdtCount", "Pictures", s.ppdtCount, 1, banks.tatCount)}</div></div><div class="settings-section"><h3>SRT & interview</h3><div class="field-grid four">${num("srtSeconds", "SRT seconds", s.srtSeconds, 1, 120)}${num("srtCount", "SRT items", s.srtCount)}${num("interviewSeconds", "Interview sec", s.interviewSeconds)}${num("interviewCount", "Interview items", s.interviewCount)}</div></div><div class="settings-section"><h3>Session behaviour</h3><div class="settings-toggles"><label class="check-field"><input id="settingShuffle" type="checkbox" ${s.shuffle ? "checked" : ""}/><span><b>Shuffle</b><small>Randomize source order.</small></span></label><label class="check-field"><input id="settingDedupe" type="checkbox" ${s.dedupe ? "checked" : ""}/><span><b>Suppress duplicates</b><small>Only the practice run changes.</small></span></label><label class="check-field"><input id="settingBeep" type="checkbox" ${s.beep ? "checked" : ""}/><span><b>Sound alert</b><small>Phase transition beep.</small></span></label><label class="check-field"><input id="settingRest" type="checkbox" ${s.restEnabled ? "checked" : ""}/><span><b>Rest breaks</b><small>Between prompts.</small></span></label>${num("restSeconds", "Rest seconds", s.restSeconds, 1, 120)}</div></div><div class="modal-actions"><button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="save-settings">Save settings</button></div>`); }
function importModal() { const categories = ["WAT", "TAT", "PPDT", "SRT", "PIQ and personal interview", "GTO and group discussion", "Lecturette", "Defence and military knowledge", "Technical interview", "General SSB knowledge and other material"]; return wrap(`<div class="modal-title"><div><div class="eyebrow">CUSTOM QUESTION BANK</div><h2>Create or import prompts</h2></div>${close()}</div><p>Paste one prompt per line or import TXT, CSV, or JSON. Exact duplicates are safely excluded. Original sources are unchanged.</p><label class="field"><span>Bank name</span><input id="customBankName" placeholder="e.g. Difficult WAT revision"/></label><label class="field"><span>Source label</span><input id="customBankSource" placeholder="e.g. My own notes"/></label><label class="field"><span>Category</span><select id="customBankCategory">${categories.map(category => `<option ${category === state.mode ? "selected" : ""}>${esc(category)}</option>`).join("")}</select></label><label class="field"><span>Import file</span><input id="importFile" type="file" accept=".txt,.csv,.json,text/plain,text/csv,application/json"/></label><label class="field"><span>Prompts</span><textarea id="customPromptText" rows="10" placeholder="One prompt per line"></textarea></label><div class="modal-actions"><button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="save-import">Save question bank</button></div>`); }
function backupModal() { return wrap(`<div class="modal-title"><div><div class="eyebrow">LOCAL DATA SAFETY</div><h2>Backup & restore</h2></div>${close()}</div><p>Versioned JSON includes settings, custom banks, completed session history, reflections, and self-ratings. It does <b>not</b> include source archives, PDFs, or external image files.</p><div class="backup-grid"><div><h3>Export browser data</h3><p>Make a non-destructive copy before moving browsers or clearing data.</p><button class="btn btn-primary" data-action="export-backup">↓ Download JSON backup</button></div><div><h3>Restore browser data</h3><p>Validation occurs before import. Merge keeps current data; replacement needs confirmation.</p><label class="btn btn-secondary file-button">↑ Choose backup JSON<input id="backupFile" type="file" accept="application/json,.json"/></label></div></div><div class="modal-actions"><button class="btn btn-secondary" data-action="close-modal">Close</button></div>`); }
function restoreModal() { const data = modal.backup.data; return wrap(`<div class="modal-title"><div><div class="eyebrow">VALIDATED BACKUP</div><h2>Choose restore behavior</h2></div>${close()}</div><p>Created ${esc(new Date(modal.backup.createdAt).toLocaleString())}. Contains ${Object.values(data.customBanks || {}).flat().length} custom banks and ${(data.history || []).length} session records.</p><div class="restore-options"><button class="btn btn-primary" data-action="restore-merge">Merge with current data</button><p>Keeps current data and adds non-conflicting records.</p><button class="btn btn-danger" data-action="restore-replace">Replace current data</button><p>Requires final confirmation and overwrites browser data.</p></div><div class="modal-actions"><button class="btn btn-secondary" data-action="backup">Back</button></div>`); }
function recoveryModal() { const data = pendingRecovery; return wrap(`<div class="modal-title"><div><div class="eyebrow">INTERRUPTED SESSION</div><h2>Resume or discard?</h2></div></div><p>A ${esc(data.mode)} session from ${esc(new Date(data.savedAt || data.startedAt).toLocaleString())} was interrupted. Its timer is paused at ${fmt(data.remaining)}. Time while the app was closed is not counted.</p><p>The correct phase and stimulus are restored only if you choose Resume.</p><div class="modal-actions"><button class="btn btn-secondary" data-action="discard-recovery">Discard unfinished run</button><button class="btn btn-primary" data-action="resume-recovery">Resume paused session</button></div>`); }

function download(value, filename) { const blob = new Blob([JSON.stringify(value, null, 2)], { type: "application/json" }), url = URL.createObjectURL(blob), anchor = document.createElement("a"); anchor.href = url; anchor.download = filename; anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 0); }
function backup() { return { backupVersion: BACKUP_VERSION, app: "ZeroHour SSB Practice Suite", createdAt: new Date().toISOString(), note: "Includes browser data only; source archives and image files are not embedded.", data: { state, customBanks, history } }; }
function validateBackup(value) { if (!value || typeof value !== "object") return "The backup is not a JSON object."; if (value.backupVersion !== BACKUP_VERSION) return `Backup version ${value.backupVersion ?? "missing"} is not supported.`; if (!value.data || typeof value.data !== "object") return "The backup has no data section."; if (value.data.customBanks && typeof value.data.customBanks !== "object") return "Custom-bank data is malformed."; if (value.data.history && !Array.isArray(value.data.history)) return "History must be a list."; return ""; }
function restore(replace) { const candidate = modal?.backup, error = validateBackup(candidate); if (error) return notice(error); const data = candidate.data; if (replace) { if (!confirm("Replace current settings, custom banks, and session history with this backup? Current browser data will be removed.")) return; state = { ...DEFAULT, ...(data.state || {}), settings: { ...DEFAULT.settings, ...(data.state?.settings || {}) }, bankIds: { ...(data.state?.bankIds || {}) } }; customBanks = data.customBanks || {}; history = data.history || []; } else { state = { ...state, ...(data.state || {}), settings: { ...state.settings, ...(data.state?.settings || {}) }, bankIds: { ...state.bankIds, ...(data.state?.bankIds || {}) } }; for (const [mode, imported] of Object.entries(data.customBanks || {})) { const existing = customBanks[mode] || [], ids = new Set(existing.map(item => item.id)); customBanks[mode] = [...existing, ...(Array.isArray(imported) ? imported.map(item => ids.has(item.id) ? { ...item, id: uid("restored") } : item) : [])]; } const ids = new Set(history.map(item => item.id)); history = [...history, ...(data.history || []).filter(item => !ids.has(item.id))].sort((a,b) => String(b.endedAt || b.startedAt).localeCompare(String(a.endedAt || a.startedAt))).slice(0,100); } modal = null; persist(); notice(replace ? "Backup restored by replacement." : "Backup merged; existing data was retained."); }
function parseText(text, filename, mode) { if (filename.toLowerCase().endsWith(".json")) { try { const raw = JSON.parse(text), values = Array.isArray(raw) ? raw : raw.items || raw.questions || raw.prompts || []; return { items: values.map((value,index) => normalise(value,mode,{id:"import",source:raw.source || "Imported file"},index)).filter(item => prompt(item,mode)), rejected: 0 }; } catch (error) { return { items: [], rejected: 1, error: "The JSON file could not be parsed." }; } } const lines = text.split(/\r?\n/).map(value => value.trim()).filter(Boolean); const values = lines.map(value => filename.toLowerCase().endsWith(".csv") ? value.split(",")[0].replace(/^['"]|['"]$/g, "").trim() : value.replace(/^\s*(?:\d{1,4}\s*[.)]|[-•*])\s*/, "").trim()).filter(Boolean); return { items: values.map((value,index) => normalise(value,mode,{id:"import",source:"Imported text"},index)), rejected: lines.length - values.length }; }
function saveImport() { const parsed = parseText($("#customPromptText")?.value || "", ".txt", state.mode); if (!parsed.items.length) return notice("Enter one prompt per line or choose a supported import file."); const result = unique(parsed.items, state.mode), id = uid("custom"), bank = { id, title: ($("#customBankName")?.value || "Untitled custom bank").trim(), source: ($("#customBankSource")?.value || "User-created material").trim(), category: $("#customBankCategory")?.value || state.mode, createdAt: new Date().toISOString(), items: result.kept, stats: { valid: result.kept.length, duplicates: result.duplicates, rejected: parsed.rejected || 0, failed: 0 } }; customBanks[state.mode] = [...(customBanks[state.mode] || []), bank]; state.bankIds[state.mode] = id; modal = null; persist(); notice(`${bank.stats.valid} valid prompts saved. ${bank.stats.duplicates} duplicates were excluded.`); }
function exportSession(record) { if (!record) return; download({ exportVersion: 1, type: "zerohour-session", id: record.id, mode: record.mode, bank: { id: record.bankId, title: record.bankTitle, source: record.source }, startedAt: record.startedAt, endedAt: record.endedAt, elapsedSeconds: record.elapsed || elapsed(record), endedEarly: Boolean(record.endedEarly), selfEvaluation: { rating: record.selfRating || "", note: record.note || "", focusTopics: record.focusTopics || "" }, items: record.items.map((item,index) => ({ order: index + 1, id: item.id, prompt: prompt(item, record.mode), source: item.source, page: item.page || null, category: item.category || record.mode, status: record.itemStatus?.[item.id] || "shown", image: imageMode(record.mode) ? item.image : undefined, referenceAnswer: record.mode === "INTERVIEW" ? item.answer || "" : undefined })) }, `zerohour-session-${record.mode.toLowerCase()}-${record.id}.json`); }

function action(name, element, event) {
  if (name === "mode") { if (session && !session.completed && !confirm("Discard the current unfinished session? Completed history will remain untouched.")) return; if (session && !session.completed) discard(); state.mode = element.dataset.mode; currentView = "practice"; persist(); render(); }
  if (name === "view") { if (session && !session.completed && !confirm("Leave and discard the active unfinished session? You can pause it if you intend to resume.")) return; if (session && !session.completed) discard(); currentView = element.dataset.view; reviewId = null; render(); }
  if (name === "settings") { modal = { type: "settings" }; render(); }
  if (name === "backup") { modal = { type: "backup" }; render(); }
  if (name === "import") { modal = { type: "import" }; render(); }
  if (name === "close-modal") { if (element.classList.contains("modal-backdrop") && event.target !== element) return; modal = null; render(); }
  if (name === "save-settings") { const s = state.settings, value = (id, fallback, min = 1, max = 5000) => { const n = Number($("#"+id)?.value); return Number.isFinite(n) ? Math.max(min, Math.min(max, Math.floor(n))) : fallback; }; Object.assign(s, { watSeconds:value("watSeconds",s.watSeconds,1,120),watCount:value("watCount",s.watCount),tatObserve:value("tatObserve",s.tatObserve,1,300),tatStory:value("tatStory",s.tatStory,1,3600),tatCount:value("tatCount",s.tatCount,1,banks.tatCount),ppdtObserve:value("ppdtObserve",s.ppdtObserve,1,300),ppdtStory:value("ppdtStory",s.ppdtStory,1,3600),ppdtNarrate:value("ppdtNarrate",s.ppdtNarrate,1,600),ppdtCount:value("ppdtCount",s.ppdtCount,1,banks.tatCount),srtSeconds:value("srtSeconds",s.srtSeconds,1,120),srtCount:value("srtCount",s.srtCount),interviewSeconds:value("interviewSeconds",s.interviewSeconds,1,3600),interviewCount:value("interviewCount",s.interviewCount),restSeconds:value("restSeconds",s.restSeconds,1,120),shuffle:Boolean($("#settingShuffle")?.checked),dedupe:Boolean($("#settingDedupe")?.checked),beep:Boolean($("#settingBeep")?.checked),restEnabled:Boolean($("#settingRest")?.checked) }); modal=null; persist(); notice("Settings saved locally."); }
  if (name === "start") { capture(); start(); }
  if (name === "pause") pause(); if (name === "resume") resume(); if (name === "restart") restart(); if (name === "skip") skip();
  if (name === "finish" && confirm("Finish this session now and save the stimuli seen so far for review?")) complete(true);
  if (name === "mute") { state.settings.beep = !state.settings.beep; persist(); render(); }
  if (name === "new-run") { session = null; start(); } if (name === "setup") { session = null; render(); }
  if (name === "preset") { const seconds = Number(element.dataset.seconds), s = state.settings; if (state.mode === "WAT") s.watSeconds=seconds; else if (state.mode === "SRT") s.srtSeconds=seconds; else if (state.mode === "INTERVIEW") s.interviewSeconds=seconds; else if (state.mode === "TAT") s.tatStory=seconds; else s.ppdtStory=seconds; persist(); render(); }
  if (name === "save-import") saveImport();
  if (name === "export-backup") { download(backup(), `zerohour-backup-${new Date().toISOString().slice(0,10)}.json`); notice("Backup downloaded. It contains browser data, not source image files."); }
  if (name === "restore-merge") restore(false); if (name === "restore-replace") restore(true);
  if (name === "resume-recovery") { session = pendingRecovery; pendingRecovery = null; modal = null; session.paused = true; session.activeStartedAt = null; session.completed = false; clearActive(); render(); }
  if (name === "discard-recovery") { pendingRecovery = null; clearActive(); modal = null; notice("Interrupted session discarded; completed history was kept."); }
  if (name === "delete-bank") { const bank = findCustom(element.dataset.mode, element.dataset.bank); if (!bank || !confirm(`Delete custom bank “${bank.title}”? Export a backup first if you may need it.`)) return; customBanks[element.dataset.mode] = (customBanks[element.dataset.mode] || []).filter(item => item.id !== bank.id); if (state.bankIds[element.dataset.mode] === bank.id) delete state.bankIds[element.dataset.mode]; persist(); notice("Custom bank deleted. Original material and session history were not changed."); }
  if (name === "export-bank") { const bank = findCustom(element.dataset.mode, element.dataset.bank); if (bank) download({ exportVersion: 1, type:"zerohour-custom-bank", mode:element.dataset.mode, ...bank }, `zerohour-bank-${bank.id}.json`); }
  if (name === "export-session") exportSession(history.find(item => item.id === element.dataset.id) || (session?.id === element.dataset.id ? session : session));
  if (name === "review") { reviewId = element.dataset.id; currentView = "history"; render(); } if (name === "history") { reviewId = null; currentView = "history"; render(); }
  if (name === "clear-history" && confirm("Clear all completed session records from this browser? Export a backup first if you may need them.")) { history=[]; persist(); render(); }
  if (name === "save-notes") { const record = history.find(item => item.id === element.dataset.id) || (session?.id === element.dataset.id ? session : null); if (!record) return; record.note=$("#sessionNote")?.value || ""; record.selfRating=$("#selfRating")?.value || ""; record.focusTopics=$("#focusTopics")?.value || ""; if (session?.id === record.id) session = record; persist(); notice("Reflection saved to this session’s local record."); }
  if (name === "fullscreen") { if (!document.fullscreenEnabled) return notice("Fullscreen is not supported or is disabled by this browser."); (document.fullscreenElement ? document.exitFullscreen() : document.documentElement.requestFullscreen()).catch(() => notice("Fullscreen request was denied. The session remains usable.")); }
}

app.addEventListener("click", event => { const element = event.target.closest("[data-action]"); if (element) action(element.dataset.action, element, event); });
app.addEventListener("change", event => { if (event.target.id === "importFile") { const file=event.target.files?.[0]; if (!file) return; const reader=new FileReader(); reader.onerror=()=>notice("The selected prompt file could not be read."); reader.onload=()=>{ const parsed=parseText(String(reader.result || ""),file.name,state.mode), area=$("#customPromptText"), title=$("#customBankName"); if(area) area.value=parsed.items.map(item=>prompt(item,state.mode)).join("\n"); if(title && !title.value) title.value=file.name.replace(/\.[^.]+$/,""); if(parsed.error) notice(parsed.error); }; reader.readAsText(file); } if (event.target.id === "backupFile") { const file=event.target.files?.[0]; if (!file) return; const reader=new FileReader(); reader.onerror=()=>notice("The selected backup could not be read."); reader.onload=()=>{ let value; try { value=JSON.parse(String(reader.result || "")); } catch(error) { return notice("The selected file is not valid JSON."); } const error=validateBackup(value); if(error) return notice(error); modal={type:"restore",backup:value}; render(); }; reader.readAsText(file); } if (event.target.id === "libraryCategory") { libraryCategory=event.target.value; render(); } });
app.addEventListener("input", event => { if (event.target.id === "librarySearch") { libraryQuery=event.target.value; render(); } });
app.addEventListener("error", event => { const image=event.target; if (image instanceof HTMLImageElement && image.classList.contains("stimulus-image")) { const stage=image.closest(".image-stage"); if(stage) stage.innerHTML=`<div class="image-fallback"><b>Stimulus image unavailable</b><small>${esc(image.dataset.imagePath || "The local image path is missing.")}</small></div>`; } }, true);
document.addEventListener("fullscreenchange", render);
document.addEventListener("keydown", event => {
  if (event.key === "Escape" && modal) { modal = null; render(); return; }
  const target = event.target;
  const typing = target && typeof target.matches === "function" && target.matches("input,textarea,select,[contenteditable]");
  if (typing) return;
  if (!session || session.completed) return;
  if (event.code === "Space") { event.preventDefault(); session.paused ? resume() : pause(); }
  else if (event.key === "ArrowRight") { event.preventDefault(); skip(); }
  else if (event.key === "r" || event.key === "R") { event.preventDefault(); restart(); }
});
document.addEventListener("visibilitychange", () => { if (document.hidden && session && !session.completed && !session.paused) pause("browser hidden or interrupted"); });
window.addEventListener("beforeunload", () => saveActive("browser closed or refreshed"));

setupSaved();
fetch("data/banks.json").then(response => { if (!response.ok) throw new Error(`Could not load reference banks (${response.status})`); return response.json(); }).then(data => { banks=data; render(); if (pendingRecovery && !pendingRecovery.completed) { modal={type:"recovery"}; render(); } return fetch("materials/reports/materials-manifest.json"); }).then(response => response.ok ? response.json() : null).then(manifest => { materialManifest=manifest; render(); }).catch(error => { if (!banks) app.innerHTML=`<div class="load-error"><h1>ZeroHour could not load its reference banks</h1><p>Run this folder through the supplied local server rather than opening it directly.</p><code>Run-Localhost-Windows.bat</code><small>${esc(error.message)}</small></div>`; else console.warn("Material manifest unavailable",error); });
